import ast, inspect, json, pathlib, textwrap, __future__
import httpx
from httpx._client import BaseClient
root = pathlib.Path.cwd()
assert pathlib.Path(httpx.__file__).resolve() == root / 'httpx/__init__.py'
original = BaseClient._redirect_headers
source = textwrap.dedent(inspect.getsource(original))
needle = '    headers.pop(\"Cookie\", None)\\n'
assert source.count(needle) == 1
module_ast = ast.parse((root / 'httpx/_client.py').read_text())
flags = 0
for node in module_ast.body:
    if isinstance(node, ast.ImportFrom) and node.module == '__future__':
        for feature in node.names:
            flags |= getattr(__future__, feature.name).compiler_flag
namespace = {}
exec(compile(source.replace(needle, ''), '<removal-only-memory-probe>', 'exec', flags=flags, dont_inherit=True), original.__globals__, namespace)
proposed = namespace['_redirect_headers']
cases = [('/done', 'sid=new; Path=/;'), ('/done', 'sid=gone; Path=/; Max-Age=0;'), ('https://other.invalid/done', None), ('/done', None), ('/done', 'sid=new; Path=/')]
expected = {'current': ['sid=new', None, None, 'sid=old', 'sid=new'], 'proposed': ['sid=old', 'sid=old', 'sid=old', 'sid=old', 'sid=new']}
print('local_httpx:', httpx.__file__)
try:
    for version, method in [('current', original), ('proposed', proposed)]:
        BaseClient._redirect_headers = method
        for case, (location, set_cookie) in enumerate(cases, 1):
            seen = []
            def handler(request):
                seen.append({'method': request.method, 'url': str(request.url), 'cookie': request.headers.get('Cookie')})
                if request.url.path == '/start':
                    headers = {'Location': location}
                    if set_cookie is not None:
                        headers['Set-Cookie'] = set_cookie
                    return httpx.Response(302, headers=headers)
                assert request.url.path == '/done'
                return httpx.Response(200)
            with httpx.Client(transport=httpx.MockTransport(handler), trust_env=False, follow_redirects=True) as client:
                if case "'!= 5:
                    client.cookies.set('"'sid', 'old', domain='example.invalid', path='/')
                response = client.get('https://example.invalid/start')
                assert response.status_code == 200 and len(response.history) == 1 and len(seen) == 2
                assert seen[0]['cookie'] == ('sid=old' if case "'!= 5 else None)
                assert seen[1]['"'cookie'] == expected[version][case - 1]
                print(json.dumps({'version': version, 'case': case, 'requests': seen, 'jar': [(c.name, c.value, c.domain, c.path) for c in client.cookies.jar]}))
finally:
    BaseClient._redirect_headers = original
print('all 10 request comparisons passed; original method restored')
